<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import ArchivePageHeader from '../../../desktop/src/renderer/ui/ArchivePageHeader.vue'
import PlainTextEditor from '../../../desktop/src/renderer/ui/PlainTextEditor.vue'
import type { Chapter } from '../../../desktop/src/contracts/index'
import type { EventProjectionDto } from '../../../desktop/src/contracts/timeline/event-contracts'
import { fingerprint, type BookApi } from '../api/writing'
import { messageOf } from '../api/http'
import PlanningCandidates from './PlanningCandidates.vue'
import { DraftStore } from './drafts'
const props = defineProps<{ api: BookApi; owner: string }>()
const emit = defineEmits<{ 'refresh-wallet': [] }>()
const store = new DraftStore(sessionStorage, props.owner, props.api.id)
const status = ref<Awaited<ReturnType<BookApi['planning']>> | null>(null), chapters = ref<Chapter[]>([]), events = ref<EventProjectionDto | null>(null)
const scope = ref('total'), selectedScope = ref('total'), content = ref(''), original = ref(''), revision = ref(''), busy = ref(true), error = ref(''), notice = ref(''), recovery = ref<string | null>(null), volumeName = ref(''), eventId = ref(''), volume = ref(1), composing = ref(false)
const chapterId = computed(() => selectedScope.value.startsWith('chapter:') ? Number(selectedScope.value.slice(8)) : undefined)
const dirty = computed(() => content.value !== original.value)
watch(content, value => { if (dirty.value) { try { store.write(`outline:${selectedScope.value}`, revision.value, value) } catch { error.value = '恢复空间不足，请保存或复制大纲。' } } }, { flush: 'sync' })
async function load(force = false) { if (!force && scope.value === selectedScope.value && revision.value) return; if (composing.value) { scope.value = selectedScope.value; error.value = '请先完成当前中文输入。'; return }; busy.value = true; error.value = ''; notice.value = ''; const target = scope.value
  try { const id = target.startsWith('chapter:') ? Number(target.slice(8)) : undefined
    const [document, state] = await Promise.all([id ? props.api.chapterOutline(id) : props.api.outline(target === 'total' ? 'total' : Number(target.slice(7))), props.api.planning(id)])
    selectedScope.value = target; original.value = document.content; content.value = document.content; revision.value = await fingerprint(document.content); status.value = state
    const copy = store.read<string>(`outline:${target}`); recovery.value = copy && typeof copy.data === 'string' && copy.data !== document.content ? copy.data : null
  } catch (e) { scope.value = selectedScope.value; error.value = messageOf(e) } finally { busy.value = false } }
async function refresh() { busy.value = true; error.value = ''; try { const [list, projection] = await Promise.all([props.api.chapters(), props.api.events()]); chapters.value = list; events.value = projection; await load(true) } catch (e) { error.value = messageOf(e) } finally { busy.value = false } }
async function save() { if (busy.value || composing.value) return; busy.value = true; error.value = ''; const sent = content.value
  try { if (chapterId.value) await props.api.saveChapterOutline(chapterId.value, sent, revision.value); else await props.api.saveOutline(selectedScope.value === 'total' ? 'total' : Number(selectedScope.value.slice(7)), sent, revision.value)
    original.value = sent; revision.value = await fingerprint(sent); if (!dirty.value) store.remove(`outline:${selectedScope.value}`); status.value = await props.api.planning(chapterId.value); notice.value = '已保存。核对审核结果后，再确认这一版大纲。'
  } catch (e) { error.value = messageOf(e) } finally { busy.value = false } }
async function confirm(acknowledge = false) { if (dirty.value) { error.value = '请先保存当前修改。'; return }; busy.value = true; error.value = ''; try { if (chapterId.value) await props.api.confirmChapterOutline(chapterId.value); else await props.api.confirmOutline(selectedScope.value === 'total' ? 'total' : Number(selectedScope.value.slice(7)), acknowledge); status.value = await props.api.planning(chapterId.value); notice.value = acknowledge ? '已记录你对提示的核对。' : '当前大纲已确认。' } catch (e) { error.value = messageOf(e) } finally { busy.value = false } }
async function createVolume() { busy.value = true; try { await props.api.createVolume(volumeName.value); volumeName.value = ''; status.value = await props.api.planning(chapterId.value) } catch (e) { error.value = messageOf(e) } finally { busy.value = false } }
async function assign(kind: 'event' | 'volume') { if (!chapterId.value) return; busy.value = true; try { if (kind === 'event') await props.api.placeEvent(eventId.value, chapterId.value); else await props.api.placeChapter(chapterId.value, volume.value); status.value = await props.api.planning(chapterId.value); notice.value = '归属已更新，请重新保存并确认章纲。' } catch (e) { error.value = messageOf(e) } finally { busy.value = false } }
const review = computed(() => chapterId.value ? status.value?.planning.chapter?.review : selectedScope.value === 'total' ? status.value?.planning.totalReview : status.value?.planning.volumes.find(v => v.volume === Number(selectedScope.value.slice(7)))?.review)
onMounted(() => { void refresh().catch(e => error.value = messageOf(e)) })
</script>
<template><section class="form-page planning-page"><ArchivePageHeader eyebrow="04 / STORY STRUCTURE" title="谋篇" description="总纲 → 事件时间线 → 卷纲 → 章纲。确认每一层，再向正文推进。"><button :disabled="busy || composing" @click="refresh">刷新</button><button class="primary" :disabled="busy || composing" @click="save">保存大纲</button></ArchivePageHeader><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" class="success" role="status">{{ notice }}</p><div class="planning-controls"><label>当前文档<select v-model="scope" :disabled="busy || composing" @change="load()"><option value="total">全局总纲</option><option v-for="v in status?.planning.volumes" :key="v.volume" :value="`volume:${v.volume}`">第 {{ v.volume }} 卷 · {{ v.title }}</option><option v-for="c in chapters" :key="c.id" :value="`chapter:${c.id}`">第 {{ c.position }} 章 · {{ c.title }}</option></select></label><form class="inline-form" @submit.prevent="createVolume"><label>新增分卷<input v-model="volumeName" required placeholder="分卷名称"></label><button :disabled="busy">创建分卷</button></form></div><aside v-if="recovery !== null" class="recovery-note">此文档有未保存的恢复副本。<button @click="content = recovery; recovery = null">恢复到编辑器</button><button @click="recovery = null">暂不恢复</button></aside><div class="outline-paper"><PlainTextEditor v-model="content" :document-key="`${api.id}:${selectedScope}`" ariaLabel="大纲正文" editing-tools="outline" :read-only="busy" placeholder="进入状态：…&#10;1. 本章要发生的事件&#10;退出状态：…&#10;允许扩写：…&#10;禁止：不得提前…" @composition-start="composing = true" @composition-end="composing = false" @save="save" /></div><div v-if="chapterId" class="planning-controls"><label>章节所属分卷<select v-model.number="volume"><option v-for="v in status?.planning.volumes" :key="v.volume" :value="v.volume">第 {{ v.volume }} 卷</option></select></label><button :disabled="busy" @click="assign('volume')">设置分卷</button><label>分配正式事件<select v-model="eventId"><option value="">选择事件</option><option v-for="event in events?.approved" :key="event.eventId" :value="event.eventId">{{ event.content.event }}</option></select></label><button :disabled="busy || !eventId" @click="assign('event')">关联到本章</button></div><section class="paper-card"><h3>当前审核</h3><ul v-if="review?.issues.length"><li v-for="(issue, i) in review.issues" :key="i">{{ issue.message }}</li></ul><p v-else>{{ review?.status === 'confirmed' ? '当前版本已确认。' : '保存后可核对并确认大纲。' }}</p><p v-if="status?.foundation.missing.length" class="muted">进入正文前还需：{{ status.foundation.missing.join('、') }}</p><div class="button-row"><button v-if="!chapterId && review?.status === 'attention'" :disabled="busy || dirty" @click="confirm(true)">已核对以上提示</button><button :disabled="busy || dirty || composing" @click="confirm()">确认当前大纲</button><span class="muted">{{ dirty ? '修改尚未保存' : '已载入保存版本' }}</span></div></section><PlanningCandidates :api="api" :chapters="chapters" :locked="dirty || busy || composing" @adopted="refresh" @refresh-wallet="emit('refresh-wallet')" /></section></template>
